class OptimalTouringCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        sites_data = message.message[0].data[0]
        visited_sites = self.determine_visiting_order(sites_data)
        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=visited_sites, type='custom')]
        )

    def determine_visiting_order(self, sites_data: Dict[int, Dict[str, int]]) -> List[int]:
        sites = list(sites_data.keys())
        travel_times = self.calculate_travel_times(sites_data)
        values = [sites_data[site]['value'] for site in sites]
        begin_hours = [sites_data[site]['beginhour'] for site in sites]
        end_hours = [sites_data[site]['endhour'] for site in sites]
        desired_times = [sites_data[site]['desiredtime'] for site in sites]

        max_value = 0
        best_path = []

        for path in itertools.permutations(sites):
            path_value = 0
            path_time = 0
            is_valid_path = True

            for i, site in enumerate(path):
                if i > 0:
                    path_time += travel_times[path[i-1]][site]
                path_time += desired_times[site - 1]
                if path_time > end_hours[site - 1] * 60 or path_time < begin_hours[site - 1] * 60:
                    is_valid_path = False
                    break
                path_value += values[site - 1]

            if is_valid_path and path_value > max_value:
                max_value = path_value
                best_path = list(path)

        return best_path

    def calculate_travel_times(self, sites_data: Dict[int, Dict[str, int]]) -> Dict[int, Dict[int, int]]:
        travel_times = {}
        sites = list(sites_data.keys())

        for site1 in sites:
            travel_times[site1] = {}
            for site2 in sites:
                if site1!= site2:
                    travel_time = abs(sites_data[site1]['avenue'] - sites_data[site2]['avenue']) + abs(sites_data[site1]['street'] - sites_data[site2]['street'])
                    travel_times[site1][site2] = travel_time

        return travel_times

