        sites_data = message.message[0].data[0]
        visited_sites = []
        current_time = min(site['beginhour'] for site in sites_data.values())
        available_sites = {site_id: site for site_id, site in sites_data.items() if site['beginhour'] <= current_time}

        while available_sites:
            best_site_id = None
            best_ratio = 0
            for site_id, site in available_sites.items():
                ratio = site['value'] / site['desiredtime']
                if ratio > best_ratio:
                    best_ratio = ratio
                    best_site_id = site_id

            if best_site_id is None:
                break

            best_site = available_sites[best_site_id]
            visited_sites.append(best_site_id)
            current_time += best_site['desiredtime']
            if current_time > best_site['endhour']:
                break

            del available_sites[best_site_id]
            current_time += self.calculate_travel_time(best_site, available_sites)
            available_sites = {site_id: site for site_id, site in available_sites.items() if site['beginhour'] <= current_time}

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=visited_sites, type='custom')]
        )

    def calculate_travel_time(self, current_site, available_sites):
        if not available_sites:
            return 0

        min_distance = float('inf')
        for site in available_sites.values():
            distance = abs(current_site['avenue'] - site['avenue']) + abs(current_site['street'] - site['street'])
            if distance < min_distance:
                min_distance = distance

        return min_distance

