            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=visited_sites, type='custom')]
        )

    def find_optimal_sequence(self, sites_data: Dict[int, Dict[str, int]]) -> List[int]:
        # Calculate Manhattan distance between each pair of sites
        distances = {}
        for site1 in sites_data:
            for site2 in sites_data:
                if site1!= site2:
                    distance = abs(sites_data[site1]['avenue'] - sites_data[site2]['avenue']) + abs(sites_data[site1]['street'] - sites_data[site2]['street'])
                    distances[(site1, site2)] = distance

        # Sort sites by opening hours
        sorted_sites = sorted(sites_data, key=lambda x: sites_data[x]['beginhour'])

        # Initialize visited sites list and current time
        visited_sites = []
        current_time = 0

        # Iterate over sorted sites
        for site in sorted_sites:
            # Check if we can visit the site without exceeding the closing hour
            if current_time + sites_data[site]['desiredtime'] <= sites_data[site]['endhour'] * 60:
                visited_sites.append(site)
                current_time += sites_data[site]['desiredtime']
                # Add travel time to the next site
                if visited_sites:
                    previous_site = visited_sites[-2]
                    current_time += distances[(previous_site, site)]

        return visited_sites

