class OptimalTouringCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def manhattan_distance(self, site1, site2):
        return abs(site1['avenue'] - site2['avenue']) + abs(site1['street'] - site2['street'])

    def receive_message(self, message: Info) -> Info:
        sites_data = message.message[0].data[0]
        sites = list(sites_data.values())
        visited_sites = []
        current_time = min(site['beginhour'] for site in sites)
        current_location = {'avenue': 0,'street': 0}
        while sites:
            nearest_site = None
            min_distance = float('inf')
            best_value = 0
            for site in sites:
                distance = self.manhattan_distance(current_location, site)
                if site['beginhour'] <= current_time <= site['endhour'] and site['value'] > best_value:
                    if distance < min_distance:
                        min_distance = distance
                        nearest_site = site
                        best_value = site['value']
                    elif distance == min_distance and site['value'] > best_value:
                        nearest_site = site
                        best_value = site['value']
            if nearest_site:
                visited_sites.append(list(sites_data.keys())[list(sites_data.values()).index(nearest_site)])
                current_time += nearest_site['desiredtime'] + min_distance
                current_location = nearest_site
                sites.remove(nearest_site)
            else:
                break
        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=visited_sites, type='custom')]
        )
